INSERT INTO clinical_note (id, patient_id, encounter_id, author_id, category, title, content, created_at, updated_at) VALUES
    ('725473be-5cdf-53a2-b7f0-d9638383648b', 'c078186c-c437-5fa8-8a5b-a6bf8883f8bf', '11b7050d-6f4c-546a-9bf7-da0f024b363e', '16259545-f97c-531d-b9cd-6ba115379372', 'admission', 'Przyjęcie do oddziału', 'Pacjent przyjęty z powodu duszności wysiłkowej i narastających obrzęków kończyn dolnych, utrzymujących się od 5 dni. W badaniu przedmiotowym: trzeszczenia u podstawy obu płuc, obrzęki podudzi. Rozpoczęto leczenie diuretyczne.', now() - interval '76 hours', now() - interval '76 hours'),
    ('76cdea00-f4be-5456-a363-01c35b8ace71', 'c078186c-c437-5fa8-8a5b-a6bf8883f8bf', '11b7050d-6f4c-546a-9bf7-da0f024b363e', '625e824c-3b63-51c2-9e56-78cbfd0ff9a5', 'nursing', 'Obserwacja pielęgniarska', 'Pacjent w stanie ogólnym dobrym. Bilans płynów dodatni, kontynuacja leczenia moczopędnego. Masa ciała spadła o 1,2 kg w ciągu doby.', now() - interval '52 hours', now() - interval '52 hours'),
    ('814d9636-6b20-5c86-8d4c-48e6f8f21ea1', 'c078186c-c437-5fa8-8a5b-a6bf8883f8bf', 'd4f638d6-9488-5d4e-b308-a85cbf76c064', '6a2063f1-ade9-52c8-a1b0-f894c0093d46', 'consultation', 'Konsultacja kardiologiczna', 'Zalecono zwiększenie dawki furosemidu oraz kontrolę elektrolitów co 48h. Echo serca planowane w ciągu tygodnia.', now() - interval '52 hours', now() - interval '52 hours'),
    ('3abd19d9-3239-5fd6-95ce-37f7fdd77f5b', '7466c824-06b6-57f2-8bae-2f20f77d64b6', '2e790042-5ce2-543b-baee-416bf421230d', '6a2063f1-ade9-52c8-a1b0-f894c0093d46', 'admission', 'Przyjęcie - podejrzenie ACS', 'Pacjentka zgłosiła się z bólem zamostkowym o charakterze uciskowym, promieniującym do lewej ręki, trwającym ok. 40 minut. W EKG uniesienie odcinka ST w odprowadzeniach II, III, aVF. Wykonano pilną koronarografię.', now() - interval '28 hours', now() - interval '28 hours'),
    ('7e613274-ccf4-5f16-b0c2-03b0e53329be', '7466c824-06b6-57f2-8bae-2f20f77d64b6', '12e1c4f3-99c3-537c-aa2e-1c91cd4ad81a', '6a2063f1-ade9-52c8-a1b0-f894c0093d46', 'progress', 'Stan po koronarografii', 'Zabieg przebiegł bez powikłań. Implantowano stent do gałęzi okalającej. Pacjentka w stanie stabilnym, bóle wieńcowe ustąpiły.', now() - interval '19 hours', now() - interval '19 hours'),
    ('2dfde60d-69bb-5691-a3e2-fe2ce90852d7', 'a8500c41-1152-563d-b249-363417666099', 'b3c81116-d377-5ae3-a4a6-0807e9ff63d9', '0ffcc103-5e1d-5346-aeba-8f9907cce3df', 'admission', 'Przyjęcie - udar niedokrwienny', 'Pacjentka przywieziona przez zespół ratownictwa medycznego z niedowładem połowiczym prawostronnym i zaburzeniami mowy, wywiad ok. 2h. Wykonano TK głowy, włączono leczenie trombolityczne.', now() - interval '124 hours', now() - interval '124 hours'),
    ('677ed6ba-7d72-53b5-95c4-e5e95ed7243d', 'a8500c41-1152-563d-b249-363417666099', 'f5ef2086-ef06-5ab2-96d2-2e4be9d9de54', '0ffcc103-5e1d-5346-aeba-8f9907cce3df', 'consultation', 'Ocena rehabilitacyjna', 'Rozpoczęto wczesną rehabilitację ruchową. Siła mięśniowa kończyny górnej prawej 3/5, dolnej 4/5. Kontynuacja ćwiczeń.', now() - interval '100 hours', now() - interval '100 hours'),
    ('78eab1ac-7d6b-55f6-845e-2c1c06ea5f5d', 'dfb16109-f62b-5791-a571-a3652caa0ea7', '05ee0b41-7454-5a2d-a52b-8d1542df4f69', '16259545-f97c-531d-b9cd-6ba115379372', 'discharge', 'Wypis ze szpitala', 'Pacjent w stanie ogólnym dobrym, ustąpiły objawy zapalenia płuc. Zakończono antybiotykoterapię dożylną. Zalecono kontrolę w poradni POZ za 2 tygodnie.', now() - interval '244 hours', now() - interval '244 hours'),
    ('bf0e574c-0415-5112-89a0-f578b2235daf', '50c8f3fa-ea66-581a-9207-f9c4c7131d26', '74af2b98-d14c-5c03-8a89-86cf57e8c170', 'fdf3ef3c-c118-5896-aa53-c2eff5aa7a21', 'admission', 'Przyjęcie na SOR - uraz wielonarządowy', 'Pacjent po wypadku komunikacyjnym, przywieziony przez zespół LPR. Triage czerwony. Wykonano TK całego ciała, stwierdzono uraz głowy i złamanie żeber.', now() - interval '6 hours', now() - interval '6 hours'),
    ('63fd5c1d-c5b7-517f-8e46-72f924b13d92', '17a3dd05-d7d5-5211-ba70-0fc6e51cc476', '3d21b7f3-1194-590f-81b4-132e899ef5f5', '19d27aee-1c46-5dd5-a0a4-21da1fe3cf3e', 'admission', 'Przyjęcie planowe', 'Pacjent przyjęty planowo celem przygotowania do cholecystektomii laparoskopowej z powodu objawowej kamicy żółciowej.', now() - interval '52 hours', now() - interval '52 hours'),
    ('815a0099-d242-5e39-9446-1981cfa09922', '55cc6e9e-6413-58bc-88b6-6342579d8413', '46dec3d5-4cfe-5979-9904-76226e15a7a3', '16259545-f97c-531d-b9cd-6ba115379372', 'admission', 'Przyjęcie - przeniesienie', 'Pacjentka przeniesiona z innego ośrodka z powodu zaburzeń elektrolitowych w przebiegu przewlekłej choroby nerek. Stan ogólny średni.', now() - interval '172 hours', now() - interval '172 hours'),
    ('5422ecc6-c93a-584b-83f5-8b1982e6c75b', '55cc6e9e-6413-58bc-88b6-6342579d8413', '46dec3d5-4cfe-5979-9904-76226e15a7a3', '625e824c-3b63-51c2-9e56-78cbfd0ff9a5', 'nursing', 'Obserwacja pielęgniarska', 'Pacjentka wymaga pomocy przy czynnościach dnia codziennego. Ryzyko upadku - wysokie, zastosowano zabezpieczenia łóżka.', now() - interval '148 hours', now() - interval '148 hours'),
    ('26fc3938-f9d3-5fce-9576-8e05569d38ff', '2350ac70-4b44-51c1-8be3-5b736e27a2c9', '50a79ab6-d77a-52cd-a64a-9851e4ee7f65', '19d27aee-1c46-5dd5-a0a4-21da1fe3cf3e', 'discharge', 'Wypis po appendektomii', 'Zabieg appendektomii laparoskopowej przebiegł bez powikłań. Pacjent w stanie dobrym, rana goi się prawidłowo. Zalecono kontrolę w poradni chirurgicznej za 2 tygodnie.', now() - interval '28 hours', now() - interval '28 hours');
